// @ts-check
import { Http2ClientBrowser } from '../http2Client/Http2ClientBrowser.js'
import { Http2ConnectionData } from '../../utils/connectionData/Http2ConnectionData.js'

export class TransmitterHttp2Browser {
    /**
     * @returns {void}
     */
    static initialize() {}

    /**
     * @returns {void}
     */
    static activate() {}

    /**
     * @async
     * @param {Uint8Array} messageByteArray
     * @param {Http2ConnectionData} connectionData
     * @returns {Promise<Uint8Array>} responseByteArray
     */
    static async sendCommand(messageByteArray, connectionData) {
        const options = {
            isDisconnectedAfterMessage: false,
        }
        return new Http2ClientBrowser(connectionData, options).send(messageByteArray)
    }

    /**
     * @async
     * @param {any} configSource
     * @returns {void}
     */

    static setConfigSource(configSource) {}
}
